21	
22	/**
23	 * Derivation of an owner's locality (region) from its postcode and city. Kept separate from the
24	 * owner controller and the {@code Owner} model so the rule lives in one place, as a pure function
25	 * with no web or persistence dependencies. Mirrors {@link AddressNormalizer}, which does the same
26	 * for addresses.
27	 *
28	 * <p>The locality is derived by <em>preferring the postcode</em>: a present 4-digit postcode that
29	 * falls within a known region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
30	 * {@code QLD 4000-4099}) yields that region directly. Only when the postcode is absent or in no known
31	 * range does the derivation fall back to a fixed city-to-region table ({@code Sydney -> NSW},
32	 * {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); that lookup is an exact match. A city not in the
33	 * table (including {@code null}) with no region-bearing postcode derives the locality {@code UNKNOWN}.
34	 * Because the pinned cities sit in their region's postcode range this returns the same region for the
35	 * known cities, while disambiguating cities that merely share a name.
36	 */
37	public abstract class LocalityResolver {
38	
39	    /** Locality derived when neither the postcode nor the city resolves to a known region. */
40	    public static final String UNKNOWN = "UNKNOWN";
41	
42	    /** City -> canonical region. Any city not listed derives {@link #UNKNOWN}. */
43	    private static final Map<String, String> CITY_REGION = Map.of(
44	        "Sydney", "NSW",
45	        "Melbourne", "VIC",
46	        "Brisbane", "QLD");
47	
48	    /** A postcode is exactly four digits. */
49	    private static final Pattern FOUR_DIGITS = Pattern.compile("[0-9]{4}");
50	
51	    /** Region -> inclusive 4-digit postcode range {low, high}. */
52	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
53	        "NSW", new int[] {2000, 2099},
54	        "VIC", new int[] {3000, 3099},
55	        "QLD", new int[] {4000, 4099});
56	
57	    /**
58	     * Derive the canonical region, preferring the postcode over the city. A present 4-digit postcode
59	     * within a known region's range yields that region; otherwise the city-to-region table is
60	     * consulted, deriving {@link #UNKNOWN} when the city is absent or unknown.
61	     *
62	     * @param city     the owner's city (may be null)
63	     * @param postcode the owner's postcode (may be null when absent)
64	     * @return the canonical region string, or {@code UNKNOWN}
65	     */
66	    public static String resolve(String city, String postcode) {
67	        String fromPostcode = regionForPostcode(postcode);
68	        return fromPostcode != null ? fromPostcode : resolve(city);
69	    }
70	
71	    /**
72	     * Derive the canonical region for a city, or {@link #UNKNOWN} when the city is not in the
73	     * fixed city-to-region table. This is the city-only fallback; prefer
74	     * {@link #resolve(String, String)} where a postcode is available.
75	     *
76	     * @param city the owner's city (may be null)
77	     * @return the canonical region string, or {@code UNKNOWN}
78	     */
79	    public static String resolve(String city) {
80	        return CITY_REGION.getOrDefault(city, UNKNOWN);
81	    }
82	
83	    /**
84	     * The region whose fixed inclusive range contains the given 4-digit postcode, or {@code null}
85	     * when the postcode is absent, not four digits, or in no known range.
86	     */
87	    private static String regionForPostcode(String postcode) {
88	        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
89	            return null;
90	        }
91	        int value = Integer.parseInt(postcode);
92	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
93	            int[] range = entry.getValue();
94	            if (value >= range[0] && value <= range[1]) {
95	                return entry.getKey();
96	            }
97	        }
98	        return null;
99	    }
100	
101	}
